model User {
  cloudflareTokenEnc         String? // encrypted Cloudflare API token for auto-DNS (business email)
  id                         String                 @id @default(cuid())
  email                      String                 @unique
  passwordHash               String
  name                       String
  // "Login with Google": the Google account's stable subject id (`sub`) once the
  // user has linked/created via Google OAuth. NULL for password-only accounts.
  // Nullable + unique so it is additive (safe `db push`) and can never point two
  // local accounts at one Google identity.
  googleId                   String?                @unique
  // Profile picture URL from Google, stored best-effort for display. Optional.
  avatarUrl                  String?
  // Discord support-bridge identity link (see lib/discord-bridge.ts,
  // app/api/admin/discord/authorize+callback/route.ts). The real Discord user
  // id ("snowflake") of the account this Nxeon staff member proved ownership
  // of via Discord OAuth (`identify` scope). Nullable + unique for the same
  // reason as `googleId` above: a Discord account can only ever be linked to
  // one Nxeon user, and a Nxeon user has at most one linked Discord account.
  // Only ever written by app/api/admin/discord/callback/route.ts, and only for
  // the CURRENTLY SIGNED-IN staff user re-derived from the real session at
  // callback time — never trust a value carried through the OAuth `state`
  // round-trip for identity. Read at Discord-reply time
  // (lib/discord-bridge.ts's `submitDiscordReply`) to resolve WHICH Nxeon
  // staff member sent a given Discord reply, replacing the old single
  // `discord_reply_as_user_id` setting now that real per-person linking exists.
  //
  // NOT YET PUSHED to the live database — same discipline as
  // `Ticket.discordThreadId` below: this column does not exist in production
  // Postgres yet, to avoid the running production app requesting a column that
  // does not exist. Run `npx prisma db push` (then `npx prisma generate`) for
  // real once this branch is reviewed and ready to promote — every read/write
  // of this field in lib/discord-bridge.ts and the OAuth routes goes through an
  // explicit `as any`/unchecked cast until then.
  discordUserId              String?                @unique
  role                       Role                   @default(CUSTOMER)
  balanceCents               Int                    @default(0)
  suspended                  Boolean                @default(false)
  // When true, this account's spend/servers are excluded from admin REVENUE and
  // MRR figures — for the owner's own/test/staff accounts, so internal usage
  // never inflates the business numbers. See lib/admin-metrics.ts REVENUE_WHERE.
  excludeFromRevenue         Boolean                @default(false)
  // Self-reported acquisition source from the one-time "How did you hear about us?"
  // first-login prompt. null = not yet asked/answered; "skipped" = dismissed. Any
  // other value is the chosen channel (e.g. "google", "youtube", "other:<text>").
  heardAboutUs               String?
  createdAt                  DateTime               @default(now())
  servers                    Server[]
  transactions               WalletTransaction[]
  auditLogs                  AuditLog[]
  staffGrants                StaffGrant[]           @relation("StaffGrants")
  staffIpAllows              StaffIpAllow[]         @relation("StaffIpAllows")
  // The ONE company mailbox this EMPLOYEE personally owns — auto-provisioned
  // at createEmployee() time, distinct from StaffMailboxGrant below (which is
  // for OTHER mailboxes an admin additionally hands them). Null for every
  // non-EMPLOYEE role. See lib/staff-mailbox-access.ts.
  staffMailboxAddress        String?                @unique
  staffMailboxGrants         StaffMailboxGrant[]    @relation("StaffMailboxGrants")
  cannedReplies              CannedReply[]
  createdWorkBoards          WorkBoard[]            @relation("WorkBoardCreator")
  assignedWorkTasks          WorkTask[]             @relation("WorkTaskAssignee")
  createdWorkTasks           WorkTask[]             @relation("WorkTaskCreator")
  workTaskComments           WorkTaskComment[]      @relation("WorkTaskCommentAuthor")
  workTaskAttachments        WorkTaskAttachment[]   @relation("WorkTaskAttachmentUploader")
  projects                   Project[]
  sshKeys                    SshKey[]
  tickets                    Ticket[]
  ticketMessages             TicketMessage[]
  notifications              Notification[]
  // Staff-initiated DMs (see StaffDm below) — the customer side of the thread,
  // the staff member who started it, and every message this user authored
  // (staff replying, or the customer replying back) across every thread.
  staffDms                   StaffDm[]              @relation("StaffDmCustomer")
  staffDmsStarted            StaffDm[]              @relation("StaffDmCreatedBy")
  staffDmMessages            StaffDmMessage[]
  domains                    Domain[]
  invoices                   Invoice[]
  hostingAccounts            HostingAccount[]
  // Growth
  referralCode               String?                @unique
  referredById               String?
  referredBy                 User?                  @relation("Referrals", fields: [referredById], references: [id])
  referrals                  User[]                 @relation("Referrals")
  signupCreditCents          Int                    @default(0)
  referralRewardedAt         DateTime?
  couponRedemptions          CouponRedemption[]
  promoRedemptions           PromoRedemption[]
  // Security
  /// When this account proved control of `email` by following a verification
  /// link. NULL = unproven. Nullable, and deliberately NOT backfilled for the
  /// accounts that predate verification: stamping a timestamp onto an address
  /// nobody ever confirmed would fabricate the exact audit fact this column
  /// exists to record. Pre-existing accounts are exempted by CREATION DATE in
  /// lib/email-verification.ts instead, which leaves the data honest.
  emailVerifiedAt            DateTime?
  totpSecret                 String?
  totpSecretEnc              String?
  sessionVersion             Int                    @default(0)
  totpEnabled                Boolean                @default(false)
  backupCodes                String[]               @default([])
  apiTokens                  ApiToken[]
  // Preferences
  notificationPrefs          Json                   @default("{}")
  claudeBuilds               ClaudeBuild[]
  anthropicKeyEnc            String? // BYOK: encrypted Anthropic API key
  feedback                   Feedback[]
  freeMinecraftServer        FreeMinecraftServer?
  // Teams
  ownedOrgs                  Organization[]         @relation("OrgOwner")
  memberships                Membership[]
  // Billing add-ons
  giftRedemptions            GiftCode[]
  autoRechargeEnabled        Boolean                @default(false)
  autoRechargeThresholdCents Int?
  autoRechargeAmountCents    Int?
  stripeCustomerId           String?
  stripePaymentMethodId      String?
  // Display-only mirror of the saved card so Billing can render "Visa ···· 4242"
  // without a Stripe round-trip. NEVER the source of truth for charging — that is
  // always stripePaymentMethodId. Refreshed whenever a card is saved.
  cardBrand                  String?
  cardLast4                  String?
  cardExpMonth               Int?
  cardExpYear                Int?
  cardExpiryNotifiedAt       DateTime?
  // The full list of cards a customer has saved (PaymentCard.stripePaymentMethodId
  // is unique, so one Stripe payment method belongs to exactly one row/user).
  // `cardBrand`/`cardLast4`/etc above and `stripePaymentMethodId` remain a live
  // MIRROR of whichever one of these is `isPrimary` — every renewal/dunning/
  // off-session charge path still reads those columns unchanged; only the
  // billing-page "which card is on file" UI reads this list directly. See
  // `mirrorPrimaryCardToUser` in lib/stripe-cards.ts, the one place that keeps
  // the two in sync.
  paymentCards               PaymentCard[]
  // Vaulted PayPal payment method, for renewals — the PayPal analogue of
  // stripeCustomerId/stripePaymentMethodId above. Set the first time a PayPal
  // checkout requests vaulting and PayPal reports it stored (see
  // lib/paypal.ts's vault attributes + savePayPalVaultFromCapture). Display-only
  // (paypalPayerEmail) mirrors cardBrand/cardLast4 — never the source of truth
  // for charging, that is always paypalVaultId.
  paypalVaultId              String?
  paypalPayerEmail           String?
  // ---- Tax / VAT (Finding 1) ----
  // The customer's billing country as an ISO-3166 alpha-2 code (e.g. "DE", "GB").
  // This is the DESTINATION that determines the VAT/GST rate actually charged on a
  // service purchase or renewal (lib/tax.ts resolveCountryTaxRate). NULL = unknown,
  // which lib/tax.ts treats conservatively (the configured global `tax_percent`
  // fallback, 0 unless the operator set one) so existing customers see no change
  // and `displayed === charged` holds until a country is on file.
  billingCountry             String?
  // The customer's EU VAT identification number, when they are VAT-registered.
  // Enables the standard B2B "0% reverse charge" ONLY when the id is well-formed
  // AND the country is a different EU member state from the seller (lib/tax.ts).
  // A malformed id never zero-rates — it falls through to the destination consumer
  // rate, the conservative direction.
  vatId                      String?
  // ---- Spend caps / usage alerts (Finding 3) ----
  // Optional SOFT monthly budget: when this account's service spend for the
  // calendar month first crosses this figure, we email the customer once. It never
  // blocks a charge. NULL/disabled = no alert.
  budgetAlertEnabled         Boolean                @default(false)
  monthlyBudgetCents         Int?
  // "YYYY-MM" of the month a budget-crossed alert was last sent, so the mail fires
  // at most once per calendar month (idempotency for `maybeAlertBudget`).
  budgetAlertedPeriod        String?
  // Optional HARD monthly spend cap: once this account's service spend for the
  // calendar month would be exceeded by a NEW paid order or manual wallet renewal,
  // that charge is refused with a clear error (lib/spend-caps.ts assertSpendCap).
  // The automatic auto-renew sweep is deliberately NOT gated by this — a standing
  // auto-renew instruction must not silently lapse an existing server. NULL/disabled
  // = uncapped.
  spendCapEnabled            Boolean                @default(false)
  hardCapCents               Int?
  // Products
  emailSubscriptions         EmailSubscription[]
  volumes                    Volume[]
  affiliatePayouts           AffiliatePayout[]
  // Ops: freeform admin notes ABOUT this customer, and notes this user authored.
  customerNotes              CustomerNote[]         @relation("CustomerNoteSubject")
  authoredCustomerNotes      CustomerNote[]         @relation("CustomerNoteAuthor")
  nxcloudInstances           NxCloudInstance[]
  // ---- KOL / Agency partner program (lifetime per-customer attribution) ----
  // Back-relations only; no new columns on the users table (the FKs live on the
  // Partner* child models), so these are safe/additive for `prisma db push`.
  //
  // The optional partner ACCOUNT this user logs in as to see their partner portal
  // (opposite of ReferralPartner.user). A user is a partner when this is set.
  referralPartner            ReferralPartner?       @relation("PartnerAccount")
  // The durable attachment binding THIS customer to the agency/KOL that referred
  // them, for the life of the account (opposite of PartnerCustomer.customer).
  partnerAttachment          PartnerCustomer?       @relation("PartnerAttachment")
  // Every commission accrued on this customer's charges (opposite of
  // PartnerCommission.customer). Distinct from the peer-referral wallet bonus.
  partnerCommissions         PartnerCommission[]    @relation("PartnerCommissions")
  // Expenses this staff member logged in the admin Accounting section.
  expensesCreated            Expense[]
  announcementsSeen          UserAnnouncementSeen[]
  // Account-area additions (2026-09-06) — see the models at the end of this file.
  apiKeys                    ApiKey[]
  sessions                   UserSession[]
  preference                 UserPreference?
  // NxLabs (mod catalog) ratings/comments — see ModRating below.
  modRatings                 ModRating[]
  // First-run guided tours (components/nx/tour, lib/tours) — see UserTourProgress.
  tourProgress               UserTourProgress[]
}

  // Any other/unknown state (paused, prelaunch, migrating…): don't guess. Leave
  // the status as-is and report what the VM actually said.
  await audit(admin.id, "server.reconcile", `${server.hostname} ${server.vmid} → no-op (${vmState ?? "unknown"})`);
  return {
    message: `The VM reports "${vmState ?? "unknown"}"; status left unchanged. Try again once it settles.`,
  };
}

export async function adminSetUserSuspended(userId: string, suspended: boolean) {
  const admin = await requireAdmin();
  if (userId === admin.id) throw new Error("Cannot suspend yourself");
  await db.user.update({ where: { id: userId }, data: { suspended } });
  await audit(admin.id, suspended ? "admin.suspend_user" : "admin.unsuspend_user", userId);
  revalidatePath("/admin/users");
}

/** Mark an account excluded from (or restored to) admin revenue & MRR figures —
 *  for the owner's own / test / staff accounts. Revenue/MRR queries filter on
 *  `excludeFromRevenue` (see lib/admin-metrics.ts). */
export async function adminSetRevenueExcluded(userId: string, excluded: boolean) {
  const admin = await requireAdmin();
  await db.user.update({ where: { id: userId }, data: { excludeFromRevenue: excluded } });
  await audit(admin.id, excluded ? "admin.revenue_exclude" : "admin.revenue_include", userId);
  revalidatePath("/admin/users");
  revalidatePath("/admin");
  revalidatePath("/admin/analytics");
}

export async function adminCreditUser(prev: any, formData: FormData): Promise<{ error?: string }> {
  const admin = await requireAdmin();
  const userId = String(formData.get("userId") ?? "");
  const amount = Number(formData.get("amount"));
  if (!userId || !Number.isFinite(amount) || amount === 0 || Math.abs(amount) > 10000) {
    return { error: "Invalid amount." };
  }
  const cents = Math.round(amount * 100);
  await db.$transaction([
    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
    db.walletTransaction.create({
      data: { userId, amountCents: cents, description: `Admin credit adjustment` },
    }),
  ]);
  await audit(admin.id, "admin.credit_user", `user=${userId} $${amount}`);
  revalidatePath("/admin/users");
  return {};
}

// ---- Admin: freeform customer notes (internal, admin-only) ----

/** Add a freeform ops note about a customer. ADMIN-only. */
export async function adminAddCustomerNote(
  prev: any,
  formData: FormData,
): Promise<{ error?: string }> {
  const admin = await requireAdmin();
  const userId = String(formData.get("userId") ?? "");
  const body = String(formData.get("body") ?? "").trim();
  if (!userId) return { error: "Missing customer." };
  if (!body) return { error: "Note cannot be empty." };
  if (body.length > 5000) return { error: "Note is too long (5000 char max)." };
  const customer = await db.user.findUnique({ where: { id: userId }, select: { id: true } });
  if (!customer) return { error: "Customer not found." };
  await db.customerNote.create({ data: { userId, authorId: admin.id, body } });
  await audit(admin.id, "admin.add_customer_note", `user=${userId}`);
  revalidatePath(`/admin/users/${userId}`);
  return {};
}

/** Edit the body of an existing customer note. ADMIN-only. */
export async function adminEditCustomerNote(
  prev: any,
  formData: FormData,
): Promise<{ error?: string }> {
  const admin = await requireAdmin();
  const noteId = String(formData.get("noteId") ?? "");
  const body = String(formData.get("body") ?? "").trim();
  if (!noteId) return { error: "Missing note." };
  if (!body) return { error: "Note cannot be empty." };
  if (body.length > 5000) return { error: "Note is too long (5000 char max)." };
  const note = await db.customerNote.findUnique({ where: { id: noteId }, select: { userId: true } });
  if (!note) return { error: "Note not found." };
  await db.customerNote.update({ where: { id: noteId }, data: { body } });
  await audit(admin.id, "admin.edit_customer_note", `user=${note.userId} note=${noteId}`);
  revalidatePath(`/admin/users/${note.userId}`);
  return {};
}

/** Delete a customer note. ADMIN-only. */
export async function adminDeleteCustomerNote(noteId: string) {
  const admin = await requireAdmin();
  const note = await db.customerNote.findUnique({ where: { id: noteId }, select: { userId: true } });
  if (!note) return;
  await db.customerNote.delete({ where: { id: noteId } });
  await audit(admin.id, "admin.delete_customer_note", `user=${note.userId} note=${noteId}`);
  revalidatePath(`/admin/users/${note.userId}`);
}

