export function SuspendServerButton({ serverId, suspended }: { serverId: string; suspended: boolean }) {
  const [pending, start] = useTransition();
  return (
    <button
      className={suspended ? "btn-secondary" : "btn-danger"}
      disabled={pending}
      onClick={() => start(() => adminSuspendServer(serverId, !suspended))}
    >
      {suspended ? "Unsuspend" : "Suspend"}
    </button>
  );
}

/**
 * Reconcile a stranded server's DB status from its real Proxmox VM state.
 * Shown for servers stuck in ERROR (also fine for PENDING/PROVISIONING). Confirms
 * first, then surfaces the outcome message / error from the action.
 */
export function ReconcileServerButton({ serverId }: { serverId: string }) {
  const [pending, start] = useTransition();
  return (
    <button
      className="btn-secondary"
      disabled={pending}
      title="Read the real VM state from Proxmox and fix the status if it's wrong"
      onClick={() => {
        if (!confirm("Reconcile this server's status from its real Proxmox VM state?")) return;
        start(async () => {
          const res = await reconcileServerFromProxmox(serverId);
          if (res?.error) alert(res.error);
          else if (res?.message) alert(res.message);
        });
      }}
    >
      {pending ? "Reconciling…" : "Reconcile"}
    </button>
  );
}

