export async function customerCredit(userId: string, amountDollars: number, reason: string, notify: boolean, email: boolean): Promise<Ok<{ message: string }>> {
  const admin = await gate("billing");
  if (badId(userId)) return { ok: false, error: "Invalid customer." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters)." };
  const amt = Number(amountDollars);
  if (!Number.isFinite(amt) || amt === 0 || Math.abs(amt) > 5000) return { ok: false, error: "Amount must be non-zero and at most ±$5,000 here." };
  const r = await adjustBalance(null, fd({ userId, amount: amt.toFixed(2), reason: why }));
  if (r.error) return { ok: false, error: r.error };
  await recordAudit(admin.id, "adminops.customer_credit", `user=${userId} ${amt >= 0 ? "+" : ""}${amt.toFixed(2)} reason="${why}"`);
  if (amt > 0) await maybeNotify(userId, notify, email, "Credit added to your account", `We've added $${amt.toFixed(2)} to your Nxeon wallet. ${why}`, "/dashboard/billing");
  return { ok: true, message: r.message ?? "Done." };
}

export async function customerRefund(userId: string, amountDollars: number, invoiceId: string, reason: string, notify: boolean, email: boolean): Promise<Ok<{ message: string }>> {
  const admin = await gate("billing");
  if (badId(userId) || (invoiceId && badId(invoiceId))) return { ok: false, error: "Invalid id." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters)." };
  const amt = Number(amountDollars);
  if (!Number.isFinite(amt) || amt <= 0) return { ok: false, error: "Enter a positive refund amount." };
  const r = await refundPayment(null, fd({ userId, amount: amt.toFixed(2), reason: why, ...(invoiceId ? { invoiceId } : {}) }));
  if (r.error) return { ok: false, error: r.error };
  await recordAudit(admin.id, "adminops.customer_refund", `user=${userId} $${amt.toFixed(2)}${invoiceId ? ` invoice=${invoiceId}` : ""} reason="${why}"`);
  await maybeNotify(userId, notify, email, "Your refund is on its way", `We've issued a refund of $${amt.toFixed(2)}.`, "/dashboard/billing");
  return { ok: true, message: r.message ?? "Refund recorded." };
}

export async function customerExtend(serverId: string, days: number, reason: string, notify: boolean, email: boolean): Promise<Ok<{ message: string }>> {
  const admin = await gate("billing");
  if (badId(serverId)) return { ok: false, error: "Invalid server." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters)." };
  const d = Math.trunc(Number(days));
  if (!Number.isFinite(d) || d === 0 || Math.abs(d) > 365) return { ok: false, error: "Days must be between -365 and 365 (not 0)." };
  const s = await db.server.findUnique({ where: { id: serverId }, select: { hostname: true, userId: true, isFree: true } });
  if (!s) return { ok: false, error: "Server not found." };
  if (s.isFree) return { ok: false, error: "Free servers have no expiry to extend." };
  const r = await adminExtendServer(null, fd({ serverId, days: String(d) }));
  if (r.error) return { ok: false, error: r.error };
  await recordAudit(admin.id, "adminops.customer_extend", `${s.hostname} ${d}d reason="${why}"`);
  if (d > 0) await maybeNotify(s.userId, notify, email, `${s.hostname} extended by ${d} day${d === 1 ? "" : "s"}`, `We've added ${d} day${d === 1 ? "" : "s"} to ${s.hostname} at no charge. ${why}`, `/dashboard/servers/${serverId}`);
  revalidateServer(serverId);
  return { ok: true, message: `${d > 0 ? "Extended" : "Shortened"} by ${Math.abs(d)} day(s).` };
}

export async function customerSetFree(serverId: string, isFree: boolean, reason: string): Promise<Ok<{ message: string }>> {
  const admin = await gate("billing");
  if (badId(serverId)) return { ok: false, error: "Invalid server." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters)." };
  await adminSetServerFree(serverId, !!isFree);
  await recordAudit(admin.id, "adminops.customer_set_free", `${serverId} -> ${!!isFree} reason="${why}"`);
  revalidateServer(serverId);
  return { ok: true, message: isFree ? "Server is now free (no billing)." : "Server is now paid (30-day term started, gifted)." };
}

/**
 * Hand a server to another account. Moves the Server row and the per-server
 * resources that are billed/managed by the owner (volumes, websites, DBs,
 * apps, cron, SSL). History (invoices, past jobs, builds, migrations, abuse
 * alerts) deliberately stays with the account it happened to. Optionally
 * rotates the root password so the previous owner's access ends.
 */
export async function customerTransferServer(serverId: string, targetEmail: string, reason: string, opts: { notify: boolean; email: boolean; resetPassword: boolean }, confirm: string): Promise<Ok<{ message: string }>> {
  const admin = await gate();
  if (badId(serverId)) return { ok: false, error: "Invalid server." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters)." };
  const s = await db.server.findUnique({ where: { id: serverId }, select: { id: true, hostname: true, userId: true, status: true, user: { select: { email: true } } } });
  if (!s) return { ok: false, error: "Server not found." };
  if (confirm.trim() !== s.hostname) return { ok: false, error: `Type the hostname (${s.hostname}) to confirm.` };
  const email = String(targetEmail ?? "").trim().toLowerCase();
  const target = await db.user.findFirst({ where: { email: { equals: email, mode: "insensitive" } }, select: { id: true, email: true, suspended: true } });
  if (!target) return { ok: false, error: "No account with that email." };
  if (target.id === s.userId) return { ok: false, error: "That account already owns this server." };
  if (target.suspended) return { ok: false, error: "The target account is suspended." };
  if (["DELETING", "PROVISIONING", "REINSTALLING"].includes(s.status)) return { ok: false, error: `Server is ${s.status} — wait until it settles.` };
  if (await inflightCount(serverId)) return { ok: false, error: "A job is in flight on this server." };
  const moved = await db.$transaction(async (tx) => {
    const counts: Record<string, number> = {};
    await tx.server.update({ where: { id: serverId }, data: { userId: target.id, projectId: null } });
    counts.volumes = (await tx.volume.updateMany({ where: { serverId }, data: { userId: target.id } })).count;
    counts.websites = (await tx.website.updateMany({ where: { serverId }, data: { userId: target.id } })).count;
    counts.databases = (await tx.vpsDatabase.updateMany({ where: { serverId }, data: { userId: target.id } })).count;
    counts.apps = (await tx.appInstall.updateMany({ where: { serverId }, data: { userId: target.id } })).count;
    counts.cron = (await tx.cronJob.updateMany({ where: { serverId }, data: { userId: target.id } })).count;
    counts.ssl = (await tx.sslCertificate.updateMany({ where: { serverId }, data: { userId: target.id } })).count;
    return counts;
  });
  if (opts.resetPassword) await db.job.create({ data: { type: "PASSWORD_RESET", serverId } });
  await recordAudit(admin.id, "adminops.transfer_server", `${s.hostname} ${s.user.email} -> ${target.email} moved=${JSON.stringify(moved)} pwReset=${!!opts.resetPassword} reason="${why}"`);
  await maybeNotify(target.id, opts.notify, opts.email, `${s.hostname} was added to your account`, `The server ${s.hostname} has been transferred to your account. ${why}`, `/dashboard/servers/${serverId}`);
  await maybeNotify(s.userId, opts.notify, false, `${s.hostname} was transferred`, `The server ${s.hostname} has been moved to another account at your request.`, "/dashboard");
  revalidateServer(serverId);

  const { sendMail, emails } = await import("./mailer");
  const link = `${process.env.APP_URL ?? "https://nxeon.cloud"}/reset-password?token=${token}`;
  const tpl = emails.passwordReset(link);
  // CRITICAL (see above): support has just told the customer "check your email".
  // A preference must not be able to make that a lie.
  if (await mayDeliverTo(user.id, "password_reset", "email")) {
    await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html });
  }
  await db.auditLog.create({ data: { userId: admin.id, action: "admin.password_reset_sent", detail: user.email } });
}

