export async function resetPassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  const token = String(formData.get("token") ?? "");
  const password = String(formData.get("password") ?? "");
  if (password.length < 8) return { error: "Password must be at least 8 characters." };
  const { createHash } = await import("node:crypto");
  const tokenHash = createHash("sha256").update(token).digest("hex");
  const row = await db.passwordResetToken.findUnique({ where: { tokenHash } });
  if (!row || row.usedAt || row.expiresAt < new Date()) {
    return { error: "This reset link is invalid or has expired. Request a new one." };
  }
  await db.$transaction([
    // Bump sessionVersion so any sessions predating the reset are evicted.
    db.user.update({
      where: { id: row.userId },
      data: { passwordHash: await bcrypt.hash(password, 12), sessionVersion: { increment: 1 } },
    }),
    db.passwordResetToken.update({ where: { id: row.id }, data: { usedAt: new Date() } }),
    db.auditLog.create({ data: { userId: row.userId, action: "user.password_reset_complete" } }),
  ]);
  return { ok: true };
}

