import { NextRequest, NextResponse } from "next/server";
import { realUser } from "@/lib/auth";
import { canAccess } from "@/lib/rbac";
import { db } from "@/lib/db";
import type { InvoiceStatus, Prisma } from "@prisma/client";
import { formatInvoiceNumber, invoiceBranding } from "@/lib/invoices";

/**
 * RBAC-checked CSV export of the current (filtered) admin table.
 *
 *   /api/admin/export?type=users&q=…
 *   /api/admin/export?type=invoices&status=OPEN
 *
 * The filter params mirror the corresponding admin page so "Export CSV" always
 * reflects what the operator is looking at. Exports the full filtered set (not
 * just the current page). Never cached.
 */
export const dynamic = "force-dynamic";

function csvCell(v: unknown): string {
  const s = v == null ? "" : String(v);
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

function toCsv(headers: string[], rows: (string | number | null | undefined)[][]): string {
  const lines = [headers.map(csvCell).join(",")];
  for (const row of rows) lines.push(row.map(csvCell).join(","));
  return lines.join("\r\n");
}

function money(cents: number): string {
  return (cents / 100).toFixed(2);
}

const INVOICE_STATUSES: InvoiceStatus[] = ["OPEN", "PAID", "VOID", "REFUNDED"];

export async function GET(req: NextRequest) {
  const user = await realUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const sp = req.nextUrl.searchParams;
  const type = sp.get("type");
  const stamp = new Date().toISOString().slice(0, 10);

  if (type === "users") {
    if (!canAccess(user.role, "clients")) {
      return NextResponse.json({ error: "forbidden" }, { status: 403 });
    }
    const query = (sp.get("q") ?? "").trim();
    const where: Prisma.UserWhereInput = query
      ? {
          OR: [
            { email: { contains: query, mode: "insensitive" } },
            { name: { contains: query, mode: "insensitive" } },
          ],
        }
      : {};

    const users = await db.user.findMany({
      where,
      include: {
        servers: {
          where: { status: { notIn: ["DELETING"] } },
          select: { isFree: true, plan: { select: { priceCents: true } } },
        },
      },
      orderBy: { createdAt: "desc" },
    });

    const csv = toCsv(
      ["id", "name", "email", "role", "balance_usd", "mrr_usd", "servers", "suspended", "joined"],
      users.map((u) => {
        const mrr = u.servers.reduce((n, s) => n + (s.isFree ? 0 : s.plan.priceCents), 0);
        return [
          u.id,
          u.name,
          u.email,
          u.role,
          money(u.balanceCents),
          money(mrr),
          u.servers.length,
          u.suspended ? "yes" : "no",
          u.createdAt.toISOString(),
        ];
      })
    );

    return new NextResponse(csv, {
      status: 200,
      headers: {
        "Content-Type": "text/csv; charset=utf-8",
        "Content-Disposition": `attachment; filename="nxeon-clients-${stamp}.csv"`,
        "Cache-Control": "private, no-store",
      },
    });
  }

  if (type === "invoices") {
    if (!canAccess(user.role, "billing")) {
      return NextResponse.json({ error: "forbidden" }, { status: 403 });
    }
    const statusParam = sp.get("status");
    const status = INVOICE_STATUSES.includes(statusParam as InvoiceStatus)
      ? (statusParam as InvoiceStatus)
      : undefined;

    const invoices = await db.invoice.findMany({
      where: status ? { status } : {},
      include: { user: { select: { email: true, name: true } } },
      orderBy: { createdAt: "desc" },
    });
    const invoiceNumberPrefix = (await invoiceBranding()).numberPrefix;

    const csv = toCsv(
      ["number", "client_name", "client_email", "status", "description", "amount_usd", "tax_usd", "issued", "paid_at"],
      invoices.map((inv) => [
        // The SAME identifier the customer sees. A CSV used for accounting or to
        // answer a support query has to reconcile against the number they quote.
        formatInvoiceNumber(inv.number, invoiceNumberPrefix),
        inv.user.name,
        inv.user.email,
        inv.status,
        inv.description,
        money(inv.amountCents),
        money(inv.taxCents),
        inv.createdAt.toISOString(),
        inv.paidAt ? inv.paidAt.toISOString() : "",
      ])
    );

    return new NextResponse(csv, {
      status: 200,
      headers: {
        "Content-Type": "text/csv; charset=utf-8",
        "Content-Disposition": `attachment; filename="nxeon-invoices-${stamp}.csv"`,
        "Cache-Control": "private, no-store",
      },
    });
  }

  return NextResponse.json({ error: "unknown export type; use ?type=users|invoices" }, { status: 400 });
}

/**
 * Tiny, dependency-free pagination helper shared across server-paginated
 * listings (originally the admin tables; NxLabs's StoreBrowser at 32k+ rows
 * per family uses it too, 2026-09-19 — see lib/mods-catalog.ts).
 *
 * Given the (already-awaited) searchParams and a total row count, it clamps the
 * requested `?page=` into range and returns the Prisma `skip`/`take` window plus
 * the resolved page number and total page count for rendering controls.
 *
 * Not a Server Action — a plain synchronous helper, safe to import anywhere.
 */
export type PageInfo = {
  skip: number;
  take: number;
  page: number;
  pages: number;
  perPage: number;
  total: number;
};

export function paginate(
  searchParams: { page?: string | string[] } | undefined,
  total: number,
  perPage = 25
): PageInfo {
  const per = Math.max(1, Math.floor(perPage) || 25);
  const pages = Math.max(1, Math.ceil(Math.max(0, total) / per));

  const rawParam = Array.isArray(searchParams?.page)
    ? searchParams?.page[0]
    : searchParams?.page;
  const raw = Number(rawParam ?? 1);
  const requested = Number.isFinite(raw) ? Math.floor(raw) : 1;
  const page = Math.min(Math.max(1, requested), pages);

  return { skip: (page - 1) * per, take: per, page, pages, perPage: per, total };
}

/**
 * Build a query string that preserves existing filters while setting `page`.
 * Values are stringified/encoded; nullish and empty values are dropped.
 */
export function pageHref(
  base: string,
  params: Record<string, string | number | undefined | null>,
  page: number
): string {
  const usp = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) {
    if (v === undefined || v === null || v === "") continue;
    usp.set(k, String(v));
  }
  usp.set("page", String(page));
  const qs = usp.toString();
  return qs ? `${base}?${qs}` : base;
}

/**
 * Like `pageHref`, but for building a full set of filter/sort/page links from
 * one place (StoreBrowser's search box, sort tabs, category chips, and
 * pager all point at the same route). Page 1 and any empty/undefined value
 * are omitted so the default view keeps a clean, canonical URL.
 */
export function buildHref(
  base: string,
  params: Record<string, string | number | undefined | null>
): string {
  const usp = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) {
    if (v === undefined || v === null || v === "") continue;
    if (k === "page" && Number(v) <= 1) continue;
    usp.set(k, String(v));
  }
  const qs = usp.toString();
  return qs ? `${base}?${qs}` : base;
}
